// Stand-in for the Paper/Bukkit API, only to compile and test XrayWatch. Not shipped.
package org.bukkit.inventory;
public class ItemStack { public final org.bukkit.Material type; public final int amount; public ItemStack(org.bukkit.Material t, int a) { type = t; amount = a; } public org.bukkit.Material getType() { return type; } public int getAmount() { return amount; } public boolean isEmpty() { return type.isAir() || amount <= 0; } public boolean hasItemMeta() { return false; } public org.bukkit.inventory.meta.ItemMeta getItemMeta() { return null; } public byte[] serializeAsBytes() { return (type.name() + "x" + amount).getBytes(java.nio.charset.StandardCharsets.UTF_8); } public static ItemStack deserializeBytes(byte[] b) { String s = new String(b, java.nio.charset.StandardCharsets.UTF_8); int i = s.lastIndexOf('x'); return new ItemStack(org.bukkit.Material.valueOf(s.substring(0, i)), Integer.parseInt(s.substring(i + 1))); } public String toString() { return type + "x" + amount; } }
